mapper.select:
SELECT us.id, us.user_id, u.username, p.name AS plan_name, p.period, us.status, us.next_delivery_date, us.create_time FROM user_subscription us LEFT JOIN subscription_plan p ON us.plan_id = p.id LEFT JOIN `user` u ON us.user_id = u.id WHERE us.deleted = 0
AND us.status = #{status}
ORDER BY us.create_time DESC
